    public Rect2I map_area(RefCounted owner,Rect2I source){var size=owner.Get("coordinate_size").AsVector2I();var scale=(Vector2)size/(Vector2)owner.Get("source_size").AsVector2I();var start=(Vector2I)((Vector2)source.Position*scale).Floor();var end=(Vector2I)((Vector2)source.End*scale).Ceil();return new Rect2I(start,end-start).Intersection(new Rect2I(Vector2I.Zero,size));}
